// Forced-set native DFS for residual E11 Wang constraints.
//
// Given residual caps (base cap minus one extra copy for each repeated point),
// preload a forced set D of distinct points and enumerate all additional points
// not in D in increasing order until the requested distinct support size is
// reached.  This covers multiset cases with repeated A-directions without the
// erroneous assumption that D must be the smallest prefix.

#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Constraint{uint8_t cap,dim;uint16_t res;uint64_t word[4];};
struct Result{double elapsed=0;bool timeout=false,complete=false,forced_valid=true;int target=19,forced_size=0,max_depth=0;uint64_t calls=0,tests=0,viol=0,solutions=0;std::array<uint64_t,20> node{};std::vector<int> forced;std::vector<int> chosen;std::vector<std::vector<int>> head;};
static bool bit4(const uint64_t w[4],int p){return (w[p>>6]>>(p&63))&1ULL;}
static bool load(const std::string&p,std::vector<Constraint>&r){std::ifstream in(p,std::ios::binary);if(!in){std::cerr<<"open fail "<<p<<"\n";return false;}char m[8];in.read(m,8);if(std::memcmp(m,"E11WANG1",8)){std::cerr<<"bad magic\n";return false;}uint32_t n;in.read((char*)&n,4);r.resize(n);for(uint32_t i=0;i<n;i++){in.read((char*)&r[i].cap,1);in.read((char*)&r[i].dim,1);in.read((char*)&r[i].res,2);for(int j=0;j<4;j++)in.read((char*)&r[i].word[j],8);}return bool(in);} 
static std::vector<std::vector<uint32_t>> point_rows(const std::vector<Constraint>&rows){std::vector<std::vector<uint32_t>>pr(256);for(uint32_t i=0;i<rows.size();i++)for(int p=1;p<=255;p++)if(bit4(rows[i].word,p))pr[p].push_back(i);return pr;}
static std::string arrj(const std::array<uint64_t,20>&a){std::ostringstream o;o<<"[";for(int i=0;i<20;i++){if(i)o<<",";o<<a[i];}o<<"]";return o.str();}
static std::string vecj(const std::vector<int>&v){std::ostringstream o;o<<"[";for(size_t i=0;i<v.size();i++){if(i)o<<",";o<<v[i];}o<<"]";return o.str();}
struct Search{const std::vector<Constraint>&rows;const std::vector<std::vector<uint32_t>>&pr;int target;double limit;std::chrono::steady_clock::time_point st;std::vector<uint8_t>cnt;std::vector<int>selected;std::array<uint8_t,256> banned{};Result res;Search(const std::vector<Constraint>&r,const std::vector<std::vector<uint32_t>>&p,int t,double l):rows(r),pr(p),target(t),limit(l),cnt(r.size(),0){banned.fill(0);}bool timed(){return limit>0&&std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()>=limit;}bool add(int q,size_t&touched){const auto&L=pr[q];touched=0;res.tests++;for(size_t i=0;i<L.size();i++){uint32_t ri=L[i];uint8_t nv=cnt[ri]+1;cnt[ri]=nv;touched=i+1;if(nv>rows[ri].cap){res.viol++;return false;}}return true;}void undo(int q,size_t touched){const auto&L=pr[q];for(size_t i=0;i<touched;i++)cnt[L[i]]--;}void dfs(int minq,int depth){if(res.timeout)return;if((res.calls++&0x3FFFULL)==0&&timed()){res.timeout=true;return;}if(depth>res.max_depth)res.max_depth=depth;if(depth==target){res.solutions++;if(res.head.size()<5){auto s=selected;std::sort(s.begin(),s.end());res.head.push_back(s);}return;}int rem=target-depth;int available=0;for(int q=minq;q<=255;q++)if(!banned[q])available++;if(available<rem)return;for(int q=minq;q<=255;q++){if(!banned[q]){size_t touched=0;bool ok=add(q,touched);if(ok){res.node[depth+1]++;selected.push_back(q);dfs(q+1,depth+1);selected.pop_back();}undo(q,touched);if(res.timeout)return;}}}Result run(std::vector<int> forced){res=Result();res.node.fill(0);res.node[0]=1;res.target=target;std::sort(forced.begin(),forced.end());forced.erase(std::unique(forced.begin(),forced.end()),forced.end());res.forced=forced;res.forced_size=(int)forced.size();std::fill(cnt.begin(),cnt.end(),0);banned.fill(0);selected.clear();st=std::chrono::steady_clock::now();std::vector<std::pair<int,size_t>> touched;for(int q:forced){if(q<1||q>255){res.forced_valid=false;break;}banned[q]=1;size_t t=0;bool ok=add(q,t);touched.push_back({q,t});if(!ok){res.forced_valid=false;break;}selected.push_back(q);res.node[selected.size()]=1;}if(res.forced_valid && (int)forced.size()<=target) dfs(1,(int)forced.size());for(auto it=touched.rbegin();it!=touched.rend();++it)undo(it->first,it->second);res.elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();res.complete=!res.timeout;res.chosen=selected;return res;}};
static std::string rj(const Result&r){std::ostringstream o;o<<"{\"elapsed_sec\":"<<std::fixed<<std::setprecision(6)<<r.elapsed<<",\"timeout\":"<<(r.timeout?"true":"false")<<",\"complete\":"<<(r.complete?"true":"false")<<",\"forced_valid\":"<<(r.forced_valid?"true":"false")<<",\"target_depth\":"<<r.target<<",\"forced\":"<<vecj(r.forced)<<",\"forced_size\":"<<r.forced_size<<",\"calls\":"<<r.calls<<",\"candidate_tests\":"<<r.tests<<",\"candidate_violations\":"<<r.viol<<",\"max_depth\":"<<r.max_depth<<",\"solutions\":"<<r.solutions<<",\"node_count_by_depth\":"<<arrj(r.node)<<",\"solutions_head\":[";for(size_t i=0;i<r.head.size();i++){if(i)o<<",";o<<vecj(r.head[i]);}o<<"]}";return o.str();}
int main(int argc,char**argv){std::string cons,outp;int target=19;double lim=60;std::vector<int>forced;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--constraints"&&i+1<argc)cons=argv[++i];else if(a=="--out"&&i+1<argc)outp=argv[++i];else if(a=="--target-depth"&&i+1<argc)target=std::stoi(argv[++i]);else if(a=="--time-limit"&&i+1<argc)lim=std::stod(argv[++i]);else if(a=="--force"&&i+1<argc){std::stringstream ss(argv[++i]);std::string tok;while(std::getline(ss,tok,','))if(!tok.empty())forced.push_back(std::stoi(tok));}else{std::cerr<<"bad arg "<<a<<"\n";return 2;}}if(cons.empty()||outp.empty()){std::cerr<<"need --constraints and --out\n";return 2;}std::vector<Constraint>rows;if(!load(cons,rows))return 1;auto pr=point_rows(rows);std::cerr<<"Loaded "<<rows.size()<<" constraints; forced="<<vecj(forced)<<" target="<<target<<"\n";Search S(rows,pr,target,lim);auto r=S.run(forced);std::cout<<rj(r)<<"\n";std::ofstream out(outp);out<<"{\n  \"status\": \"ok\",\n  \"constraints_path\": \""<<cons<<"\",\n  \"constraint_count\": "<<rows.size()<<",\n  \"result\": "<<rj(r)<<"\n}\n";std::cerr<<"Wrote "<<outp<<"\n";return 0;}
